"""Render four reviewable Markdown case notes from the pilot's JSON owners."""
import argparse
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent


def render():
    book = json.loads((HERE / "casebook.json").read_text(encoding="utf-8"))
    sources = {s["id"]: s for s in json.loads((HERE / "sources.json").read_text(encoding="utf-8"))["sources"]}
    outputs = {}
    for case in book["cases"]:
        lines = [f'# {case["id"]} — {case["title"]}', "",
                 "<!-- Generated by render_casebook.py from casebook.json and sources.json. -->", "",
                 f'**Trả lời có phạm vi:** {case["answer"]}', "",
                 "Ngày 08/11/2026. Đọc/đối chiếu tài liệu; chưa tái lập hoặc chạy thí nghiệm hệ thống. Người dùng chưa duyệt.", "",
                 f'[Câu hỏi gốc](../../GraphFlow_Research_Vault/07_Questions/{case["id"]}.md) · [Tổng quan](README.md)', "",
                 "## Trước vòng kiểm", "", case["before"], "", case["question_role"], "",
                 "Nguồn hạt giống: " + ", ".join(case["original_papers"]) + ". Claim khởi đầu: " + ", ".join(case["original_claims"]) + ".", "",
                 "## Các nhận định dùng trong câu trả lời", ""]
        used = set()
        for claim in case["claims"]:
            citations = []
            for source_id in claim["source_ids"]:
                source = sources[source_id]
                citations.append(f'[{source_id}: {source["title"]}]({source["url"]})')
                used.add(source_id)
            lines.extend([f'### {claim["id"]} — `{claim["epistemic_type"]}`', "",
                          claim["statement"], "", "Căn cứ: " + " · ".join(citations) + ".", "",
                          f'Vị trí kiểm: {claim["locator"]}.', "", f'**Giới hạn:** {claim["limitation"]}', ""])
            if claim.get("premise_claim_ids"):
                lines.extend(["Suy từ: " + ", ".join(claim["premise_claim_ids"]) + ".", ""])
        lines.extend(["## Đối chiếu làm rõ hoặc đổi cách hiểu", "", case["scope_changing_check"], "",
                      "## Tri thức dùng được", "", case["usable_knowledge"], "", "## Chưa đủ bằng chứng", ""])
        lines.extend("- " + item for item in case["remaining_unknowns"])
        probe = case["manual_probe"]
        lines.extend(["", "## Câu thử và câu trả lời thực tế", "", f'**{probe["id"]}:** {probe["question"]}', "",
                      probe["actual_answer"], "", "Căn cứ: " + ", ".join(probe["evidence_claim_ids"]) + ".", "",
                      "Câu trả lời do AI tổng hợp thủ công trong lượt đọc; chưa phải benchmark generator tự động.", "",
                      "## Quyết định và bước tiếp", "", case["decision"], "", case["next_check"], "",
                      f'Novelty: `{case["novelty_status"]}`. Giữ lịch sử câu hỏi; không chuyển thành rejected chỉ vì đã có prior art.', "",
                      "## Phiên bản và mức đọc của nguồn dùng", ""])
        for source_id in sorted(used):
            source = sources[source_id]
            lines.append(f'- **{source_id}**: {source["version"]}; `{source["read_depth"]}`; trạng thái `{source["publication_status"]}`.')
        outputs[case["id"] + ".md"] = "\n".join(lines) + "\n"
    return outputs


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for name, content in render().items():
        path = HERE / name
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                raise SystemExit("Stale or missing generated case: " + name)
        else:
            path.write_text(content, encoding="utf-8", newline="\n")
    print("Four case notes " + ("match their JSON sources." if args.check else "rendered."))


if __name__ == "__main__":
    main()
